/**
 * team_* handler 参数校验穷举矩阵：对每个 handler 的每个必填键，
 * 断言缺失时的稳定错误码与精确消息文本；可选字段的类型违规逐一覆盖。
 */
import { describe, expect, it, beforeEach } from "vitest";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createHandlers, rootCaller, type Handlers } from "../../src/plugin/handlers.js";

let home: string;
let h: Handlers;
beforeEach(() => {
  home = mkdtempSync(join(tmpdir(), "xzg-hm-"));
  h = createHandlers(home, "session-hm", rootCaller());
});

/** 对每个 handler 枚举必填键：缺任一键即 invalid-arguments + 精确消息。 */
const requiredMatrix: Array<{
  handler: keyof Handlers;
  setup?: () => Promise<void>;
  all: Record<string, string>; // 全部合法最小参数（值任意占位）
  stringRequired: string[];
  numberRequired?: string[];
}> = [
  {
    handler: "spawn",
    all: { member: "m", durable_id: "d", role: "r", tier: 1 },
    stringRequired: ["member", "durable_id", "role"],
    numberRequired: ["tier"],
  },
  {
    handler: "send",
    all: { to: "qa", from: "master", type: "info", body: null },
    stringRequired: ["to", "from", "type"],
    setup: async () => {},
  },
  { handler: "inbox", all: { member: "coder" }, stringRequired: ["member"] },
  { handler: "ack", all: { member: "coder", envelope_id: "e1" }, stringRequired: ["member", "envelope_id"] },
  { handler: "taskCreate", all: { title: "t", room: "root" }, stringRequired: ["title", "room"] },
  { handler: "taskUpdate", all: { task_id: "t1" }, stringRequired: ["task_id"] },
  { handler: "stateGet", all: { room: "root" }, stringRequired: ["room"] },
  { handler: "stateSet", all: { room: "root", role: "a", status: "running" }, stringRequired: ["room", "role", "status"] },
  { handler: "handoff", all: { task_id: "t1", to_role: "qa" }, stringRequired: ["task_id", "to_role"] },
];

describe("必填参数缺失矩阵", () => {
  for (const entry of requiredMatrix) {
    for (const key of entry.stringRequired) {
      it(`${String(entry.handler)}: 缺 ${key}`, async () => {
        if (entry.setup) await entry.setup();
        const args = { ...entry.all };
        delete args[key];
        await expect((h[entry.handler] as (a: object) => Promise<unknown>)(args)).rejects.toMatchObject({
          code: "invalid-arguments",
          message: `string field "${key}" is required`,
        });
      });
    }
    for (const key of entry.numberRequired ?? []) {
      it(`${String(entry.handler)}: 缺数值 ${key}`, async () => {
        const args = { ...entry.all };
        delete args[key];
        await expect((h[entry.handler] as (a: object) => Promise<unknown>)(args)).rejects.toMatchObject({
          code: "invalid-arguments",
          message: 'number field "tier" is required',
        });
      });
    }
  }
});

describe("可选字段类型违规矩阵", () => {
  const base = { member: "m", durable_id: "d", role: "r", tier: 1 };

  it("spawn.tier 非数字", async () => {
    await expect(h.spawn({ ...base, tier: "1" })).rejects.toMatchObject({
      code: "invalid-arguments",
      message: 'field "tier" must be a number',
    });
  });

  it("taskCreate.touched_paths 非字符串数组", async () => {
    await expect(
      h.taskCreate({ title: "t", room: "r", touched_paths: "src/a.ts" }),
    ).rejects.toMatchObject({ code: "invalid-arguments", message: 'field "touched_paths" must be a string array' });
  });

  it("taskCreate.dod 含非字符串元素", async () => {
    await expect(
      h.taskCreate({ title: "t", room: "r", dod: [1, 2] }),
    ).rejects.toMatchObject({ code: "invalid-arguments", message: 'field "dod" must be a string array' });
  });

  it("taskUpdate.rounds 非数字", async () => {
    const t = await (h.taskCreate({ title: "t", room: "r" }) as unknown as Promise<{ task_id: string }>);
    await expect(
      h.taskUpdate({ task_id: t.task_id, rounds: "many" }),
    ).rejects.toMatchObject({ code: "invalid-arguments", message: 'field "rounds" must be a number' });
  });

  it("stateSet.status 非保留态给 invalid-stage", async () => {
    await expect(h.stateSet({ room: "r", role: "a", status: "paused" })).rejects.toMatchObject({
      code: "invalid-stage",
    });
  });

  it("send.to 未注册成员给 unknown-member", async () => {
    await expect(h.send({ to: "ghost", from: "master", type: "info", body: null })).rejects.toMatchObject({
      code: "unknown-member",
      message: "recipient ghost is not registered",
    });
  });

  it("handoff 任务不存在给 task-not-found", async () => {
    await expect(h.handoff({ task_id: "nope", to_role: "qa" })).rejects.toMatchObject({
      code: "task-not-found",
      message: "task nope does not exist",
    });
  });
});

tests/plugin/heartbeat.test.ts.source:
/**
 * #97 白名单心跳触点单测（ADR 0016）：白名单工具调用成功后刷新对应成员
 * lastSeen，归属 = 事件流 actor 镜像口径；forbidden 前置失败与纯读不刷。
 * 时钟由 fake timers 控制，lastSeen 精确等于调用时刻 Date.now()。
 * send 的 body=null 已随 #131 修复支持（null 合法负载，计账行不携带 task_id）。
 */
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  createHandlers,
  rootCaller,
  memberCaller,
  type Handlers,
} from "../../src/plugin/handlers.js";
import { Registry } from "../../src/index.js";

let home: string;
let master: Handlers; // 主控会话 handler 集
let coder: Handlers; // 成员 coder 会话 handler 集
const BASE = 1_700_000_000_000;

beforeEach(() => {
  vi.useFakeTimers();
  vi.setSystemTime(BASE);
  home = mkdtempSync(join(tmpdir(), "xzg-heartbeat-"));
  master = createHandlers(home, "session-master", rootCaller());
  coder = createHandlers(home, "dur-coder", memberCaller("coder"));
});

afterEach(() => {
  vi.useRealTimers();
});

async function seedTeam(): Promise<void> {
  await master.init({});
  vi.setSystemTime(BASE + 1_000);
  await master.spawn({ member: "coder", durable_id: "dur-coder", role: "coder", tier: 1 });
}

/** 读成员当前 lastSeen（未登记返回 -1）。 */
async function seenOf(member: string): Promise<number> {
  return (await new Registry(home).getMember(member))?.lastSeen ?? -1;
}

describe("白名单心跳触点（#97 ADR 0016）", () => {
  it("team_send 刷发件人、不动收件人", async () => {
    await seedTeam(); // coder.lastSeen = BASE+1000
    vi.setSystemTime(BASE + 5_000);
    await master.send({ to: "coder", from: "master", type: "info", body: {} });
    expect(await seenOf("master")).toBe(BASE + 5_000);
    expect(await seenOf("coder")).toBe(BASE + 1_000); // 收件人不因被投递而续命
  });

  it("team_inbox readUnread 分支纯读不刷；claim 分支刷本人", async () => {
    await seedTeam();
    vi.setSystemTime(BASE + 5_000);
    const sent = (await master.send({
      to: "coder",
      from: "master",
      type: "info",
      body: { hello: true },
    })) as { envelope_id: string };
    // readUnread：纯读白名单之外。
    vi.setSystemTime(BASE + 6_000);
    await coder.inbox({ member: "coder" });
    expect(await seenOf("coder")).toBe(BASE + 1_000);
    // claim：认领是投递写副作用 → 刷本人。
    vi.setSystemTime(BASE + 7_000);
    await coder.inbox({ member: "coder", envelope_id: sent.envelope_id });
    expect(await seenOf("coder")).toBe(BASE + 7_000);
  });

  it("team_ack 刷确认者本人（#194 批刷：窗口内重复心跳合并，lastSeen=窗口首刷时刻）", async () => {
    await seedTeam();
    vi.setSystemTime(BASE + 5_000);
    const sent = (await master.send({
      to: "coder",
      from: "master",
      type: "info",
      body: { hello: true },
    })) as { envelope_id: string };
    vi.setSystemTime(BASE + 6_000);
    await coder.inbox({ member: "coder", envelope_id: sent.envelope_id }); // claim → 首刷落盘 BASE+6s 并开 30s 窗口
    vi.setSystemTime(BASE + 7_000);
    await coder.ack({ member: "coder", envelope_id: sent.envelope_id }); // 1s 后 ack：窗口内合并（内存计数免写）
    expect(await seenOf("coder")).toBe(BASE + 6_000); // 磁盘 lastSeen = 窗口首刷时刻（30s 粒度批刷）
  });

  it("#194 批刷：窗口已过 → 下一次心跳重新落盘（滞后上界 = 一个窗口 + 下一次调用）", async () => {
    await seedTeam();
    vi.setSystemTime(BASE + 5_000);
    await coder.stateSet({ room: "root", role: "coder", status: "running" });
    expect(await seenOf("coder")).toBe(BASE + 5_000); // 首刷落盘
    vi.setSystemTime(BASE + 10_000);
    await coder.heartbeatProbe?.();
    // 窗口内（BASE+5s + 30s）：合并不写。
    expect(await seenOf("coder")).toBe(BASE + 5_000);
    // 窗口外（+31s）：新窗口首刷重新落盘。
    vi.setSystemTime(BASE + 36_000);
    await coder.send({ to: "master", from: "coder", type: "info", body: {} });
    expect(await seenOf("coder")).toBe(BASE + 36_000);
  });

  it("#194 批刷：机会式冲刷——同一 handler 集内成员 B 心跳顺带把已到期窗口的成员 A 落盘", async () => {
    await seedTeam();
    vi.setSystemTime(BASE + 1_000);
    await master.spawn({ member: "qa", durable_id: "dur-qa", role: "qa", tier: 1 });
    const t1 = (await master.taskCreate({ title: "A", room: "root", assignee: "coder" })) as { task_id: string };
    const t2 = (await master.taskCreate({ title: "B", room: "root", assignee: "qa" })) as { task_id: string };
    // 主控代管 coder 认领：coder 首刷 BASE+2s，开 30s 窗口（至 BASE+32s）。
    vi.setSystemTime(BASE + 2_000);
    await master.taskUpdate({ task_id: t1.task_id, status: "running" });
    expect(await seenOf("coder")).toBe(BASE + 2_000);
    // BASE+40s 主控代管 qa 认领：qa 心跳时 coder 的窗口（BASE+32s）已到期
    // → 同 handler 集内机会式冲刷把 coder 落盘至 BASE+40s。
    vi.setSystemTime(BASE + 40_000);
    await master.taskUpdate({ task_id: t2.task_id, status: "running" });
    expect(await seenOf("coder")).toBe(BASE + 40_000);
    expect(await seenOf("qa")).toBe(BASE + 40_000);
  });

  it("team_state_set 刷分片归属 role 本人", async () => {
    await seedTeam();
    vi.setSystemTime(BASE + 5_000);
    await coder.stateSet({ room: "root", role: "coder", status: "running" });
    expect(await seenOf("coder")).toBe(BASE + 5_000);
    // 主控代写他人分片同样刷该分片 role（镜像口径）而非调用者。
    vi.setSystemTime(BASE + 6_000);
    await coder.stateSet({ room: "root", role: "ghost-shard-role", status: "done" }).catch(
      () => undefined, // 黑板对未登记角色可能拒绝；此处仅关注已登记路径
    );
    expect(await seenOf("coder")).toBe(BASE + 5_000); // 未被上一步误伤
  });

  it("team_task_update 主控代管刷 assignee 而非调用者（镜像口径）", async () => {
    await seedTeam();
    vi.setSystemTime(BASE + 3_000);
    const created = (await master.taskCreate({
      title: "任务 X",
      room: "root",
      assignee: "coder",
    })) as { task_id: string };
    vi.setSystemTime(BASE + 5_000);
    await master.taskUpdate({ task_id: created.task_id, status: "running" });
    expect(await seenOf("coder")).toBe(BASE + 5_000);
    expect(await seenOf("master")).toBe(BASE); // 调用者（tier0 主控）不被误刷
  });

  it("team_handoff 刷交接目标 to_role 而非调用者与原持有者", async () => {
    await seedTeam();
    vi.setSystemTime(BASE + 2_000);
    await master.spawn({ member: "qa", durable_id: "dur-qa", role: "qa", tier: 1 });
    const created = (await master.taskCreate({
      title: "交接我",
      room: "root",
      assignee: "coder",
    })) as { task_id: string };
    vi.setSystemTime(BASE + 6_000);
    await master.handoff({ task_id: created.task_id, to_role: "qa" });
    expect(await seenOf("qa")).toBe(BASE + 6_000);
    expect(await seenOf("coder")).toBe(BASE + 1_000); // 原持有者不因失去任务而续命
    expect(await seenOf("master")).toBe(BASE);
  });

  it("forbidden 前置失败不产生任何心跳（副作用前抛错）", async () => {
    await seedTeam();
    // 越权冒充：intruder 身份尝试以 master 名义发信 → requireSelf 拒绝。
    const intruder = createHandlers(home, "dur-intruder", memberCaller("intruder"));
    vi.setSystemTime(BASE + 9_000);
    await expect(
      intruder.send({ to: "coder", from: "master", type: "info", body: {} }),
    ).rejects.toMatchObject({ code: "forbidden" });
    expect(await seenOf("master")).toBe(BASE); // 冒充者无从给 master 续命
    expect(await seenOf("coder")).toBe(BASE + 1_000); // 收件人也不动
  });

  it("触点插入不影响既有工具返回形态与事件序列", async () => {
    await seedTeam();
    vi.setSystemTime(BASE + 5_000);
    const sent = (await master.send({
      to: "coder",
      from: "master",
      type: "info",
      body: {},
    })) as { ok: boolean; envelope_id: string };
    expect(sent.ok).toBe(true);
    expect(typeof sent.envelope_id).toBe("string");
  });
});

tests/plugin/host-tools.test.ts.source:
/**
 * Wave 1a（#120 v2 计划 1e）：工具面 handler 绑定反查后的跨会话数据通道。
 *
 * 主控侧 handlers 创建实例 + dispatch 给成员 dur-X；子代理侧 handlers（以
 * resolveTeamHomeForView("dur-X").teamHome 构造）能认领主控侧信封、task_update
 * 落主控账本可被 task_list 读到。DSH_HOME 环境隔离。
 *
 * 同时覆盖 agentless 抛错（复核必改 3）与 host.execute 反查接线。
 */
import { describe, expect, it, beforeEach, afterEach } from "vitest";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { apply } from "../../src/plugin/host.js";
import { createHandlers, memberCaller, rootCaller, type Handlers } from "../../src/plugin/handlers.js";
import { resolveTeamHome, resolveTeamHomeForView } from "../../src/plugin/team-home.js";
import { resetSessionIndex } from "../../src/plugin/session-index.js";

const SESSION_MASTER = "session-master-1";
const MEMBER = "qa";
const DUR_X = "dur-q1";

/** 轻量工具类型，用于 host.execute 断言的松散签名。 */
interface Tool {
  execute: (args: Record<string, unknown>, exec?: { agent?: { id?: string } }) => Promise<unknown>;
}

function makeHost() {
  const registered = new Map<string, Tool>();
  const ctx = {
    tools: {
      register: (d: { name: string }) => {
        registered.set(d.name, d as unknown as Tool);
        return () => registered.delete(d.name);
      },
    },
    logger: { info: () => {}, warn: () => {} },
    get: () => undefined,
  };
  const dispose = apply(ctx as never);
  return { registered, dispose };
}

let dshHome: string;

beforeEach(() => {
  const home = mkdtempSync(join(tmpdir(), "xzg-hosttools-"));
  dshHome = join(home, "dsh-home");
  process.env.DSH_HOME = dshHome;
});

afterEach(() => {
  // 反查索引单例按 DSH_HOME 隔离；逐用例清理防 fd/状态累积（ADR 0021）。
  resetSessionIndex();
});

describe("Wave 1a 工具面反查挂载（子代理 → 主控实例）", () => {
  it("子代理侧 handlers 认领主控侧信封并落主控账本", async () => {
    // 主控侧：实例根 + 任务 + dispatch。
    const masterHome = resolveTeamHome(SESSION_MASTER);
    const master = createHandlers(masterHome, SESSION_MASTER, rootCaller());
    await master.init({});
    const created = (await master.taskCreate({ title: "t", room: "root" })) as {
      ok: true;
      task_id: string;
    };
    const taskId = created.task_id;
    await master.dispatch({
      member: MEMBER,
      durable_id: DUR_X,
      role: MEMBER,
      tier: 1,
      task_id: taskId,
    });

    // 子代理侧：反查挂载主控实例根。
    const resolution = resolveTeamHomeForView(DUR_X);
    expect(resolution.membership).toEqual({ root_session: SESSION_MASTER, member: MEMBER });
    expect(resolution.teamHome).toBe(masterHome);
    const sub = createHandlers(resolution.teamHome, DUR_X, memberCaller(MEMBER));

    // inbox 读到主控侧派发信封并可认领。
    const unread = (await sub.inbox({ member: MEMBER })) as {
      ok: true;
      unread: Array<{ id: string }>;
    };
    expect(unread.unread).toHaveLength(1);
    const envelopeId = unread.unread[0]!.id;
    const claimed = (await sub.inbox({ member: MEMBER, envelope_id: envelopeId })) as {
      ok: true;
      envelope: { id: string };
    };
    expect(claimed.envelope.id).toBe(envelopeId);

    // 子代理 task_update 落主控账本：主控侧 task_list 可读。
    const updated = (await sub.taskUpdate({ task_id: taskId, status: "running", rounds: 1 })) as {
      ok: true;
      status: string;
    };
    expect(updated.status).toBe("running");
    const list = (await master.taskList({})) as {
      ok: true;
      tasks: Array<{ id: string; status: string }>;
    };
    const task = list.tasks.find((t) => t.id === taskId);
    expect(task?.status).toBe("running");
  });

  it("host.execute 子代理侧反查接主控实例（L51 接线验证）", async () => {
    const { registered } = makeHost();
    // 建主控实例态。
    await createHandlers(resolveTeamHome(SESSION_MASTER), SESSION_MASTER, rootCaller()).init({});
    // 主控侧建任务 + dispatch。
    const created = (await registered.get("team_task_create")!.execute(
      { title: "t", room: "root" },
      { agent: { id: SESSION_MASTER } },
    )) as { ok: boolean; task_id: string };
    const taskId = created.task_id;
    await registered.get("team_dispatch")!.execute(
      { member: MEMBER, durable_id: DUR_X, role: MEMBER, tier: 1, task_id: taskId },
      { agent: { id: SESSION_MASTER } },
    );
    // 子代理侧以 dur-q1 身份 inbox 读到主控派发信封。
    const inbox = (await registered.get("team_inbox")!.execute(
      { member: MEMBER },
      { agent: { id: DUR_X } },
    )) as { ok: boolean; unread: Array<{ id: string }> };
    expect(inbox.unread).toHaveLength(1);
    // 子代理侧 task_update 落主控账本。
    await registered.get("team_task_update")!.execute(
      { task_id: taskId, status: "running", rounds: 1 },
      { agent: { id: DUR_X } },
    );
    // 主控侧 task_list 读回 running。
    const list = (await registered.get("team_task_list")!.execute(
      {},
      { agent: { id: SESSION_MASTER } },
    )) as { ok: boolean; tasks: Array<{ id: string; status: string }> };
    const task = list.tasks.find((t) => t.id === taskId);
    expect(task?.status).toBe("running");
  });

  it("agentless 调用抛稳定错误码 agent-required（复核必改 3）", async () => {
    const { registered } = makeHost();
    await expect(
      registered.get("team_task_list")!.execute({}, { agent: undefined }),
    ).rejects.toMatchObject({ code: "agent-required" });
  });

  it("子代理未登记首调不缓存空解析，主控登记后自愈命中（独立审核发现）", async () => {
    const { registered } = makeHost();
    await createHandlers(resolveTeamHome(SESSION_MASTER), SESSION_MASTER, rootCaller()).init({});
    // 子代理 dur-q1 尚未被主控登记：首调反查未命中 → 走自身逻辑根，不炸，
    // 但不得把空解析写入 handlerCache。
    const before = (await registered.get("team_task_list")!.execute(
      {},
      { agent: { id: DUR_X } },
    )) as { ok: boolean; tasks: unknown[] };
    expect(before.ok).toBe(true);
    expect(before.tasks).toEqual([]);
    // 主控侧建任务 + dispatch 登记 dur-q1 并派发信封。
    const created = (await registered.get("team_task_create")!.execute(
      { title: "t", room: "root" },
      { agent: { id: SESSION_MASTER } },
    )) as { ok: boolean; task_id: string };
    await registered.get("team_dispatch")!.execute(
      { member: MEMBER, durable_id: DUR_X, role: MEMBER, tier: 1, task_id: created.task_id },
      { agent: { id: SESSION_MASTER } },
    );
    // 子代理再次调用：应重新解析并命中主控实例，读到主控派发的信封。
    const after = (await registered.get("team_inbox")!.execute(
      { member: MEMBER },
      { agent: { id: DUR_X } },
    )) as { ok: boolean; unread: Array<{ id: string }> };
    expect(after.ok).toBe(true);
    expect(after.unread).toHaveLength(1);
  });
});

describe("Wave 1b 写面收敛矩阵（#123）", () => {
  /** 主控 init + 建任务 + dispatch 给 qa，返回 { master, sub, taskId }。 */
  async function makeTeam() {
    const masterHome = resolveTeamHome(SESSION_MASTER);
    const master = createHandlers(masterHome, SESSION_MASTER, rootCaller());
    await master.init({});
    const created = (await master.taskCreate({ title: "t", room: "root" })) as {
      ok: true;
      task_id: string;
    };
    await master.dispatch({
      member: MEMBER,
      durable_id: DUR_X,
      role: MEMBER,
      tier: 1,
      task_id: created.task_id,
    });
    const sub = createHandlers(masterHome, DUR_X, memberCaller(MEMBER));
    return { master, sub, taskId: created.task_id };
  }

  it("子代理越权：spawn/dispatch/taskCreate → forbidden", async () => {
    const { sub } = await makeTeam();
    await expect(
      sub.spawn({ member: "coder", durable_id: "d2", role: "coder", tier: 1 }),
    ).rejects.toMatchObject({ code: "forbidden" });
    await expect(
      sub.dispatch({ member: "coder", durable_id: "d2", role: "coder", tier: 1, task_id: "x" }),
    ).rejects.toMatchObject({ code: "forbidden" });
    await expect(
      sub.taskCreate({ title: "x", room: "root" }),
    ).rejects.toMatchObject({ code: "forbidden" });
  });

  it("子代理越权：send from 他人 / inbox 他人 / ack 他人 / stateSet 他人分片 → forbidden", async () => {
    const { sub } = await makeTeam();
    await expect(
      sub.send({ to: "coder", from: "master", type: "info", body: { n: 1 } }),
    ).rejects.toMatchObject({ code: "forbidden" });
    await expect(sub.inbox({ member: "coder" })).rejects.toMatchObject({ code: "forbidden" });
    await expect(
      sub.ack({ member: "coder", envelope_id: "env-1" }),
    ).rejects.toMatchObject({ code: "forbidden" });
    await expect(
      sub.stateSet({ room: "root", role: "coder", status: "running" }),
    ).rejects.toMatchObject({ code: "forbidden" });
  });

  it("子代理越权：taskUpdate 他人任务 / 自己任务 patch assignee / handoff 他人任务 → forbidden", async () => {
    const { master, sub, taskId } = await makeTeam();
    // 他人任务：master 再建一个未指派任务（assignee 缺省），子代理无权更新。
    const other = (await master.taskCreate({ title: "other", room: "root" })) as {
      ok: true;
      task_id: string;
    };
    await expect(
      sub.taskUpdate({ task_id: other.task_id, status: "running" }),
    ).rejects.toMatchObject({ code: "forbidden" });
    // 自己任务 patch assignee（绕过 handoff 回执）→ forbidden。
    await expect(
      sub.taskUpdate({ task_id: taskId, status: "running", assignee: "qa" }),
    ).rejects.toMatchObject({ code: "forbidden" });
    // handoff 他人任务 → forbidden。
    await expect(
      sub.handoff({ task_id: other.task_id, to_role: "qa", receipt: ["pass: done"] }),
    ).rejects.toMatchObject({ code: "forbidden" });
    // handoff 自己任务但 to_role 未登记 → unknown-member（防 dangling assignee）。
    await expect(
      sub.handoff({ task_id: taskId, to_role: "ghost", receipt: ["pass: done"] }),
    ).rejects.toMatchObject({ code: "unknown-member" });
  });

  it("未登记会话（caller undefined）写操作 → forbidden", async () => {
    const home = resolveTeamHome("session-ghost");
    const ghost = createHandlers(home, "session-ghost", undefined);
    await expect(
      ghost.stateSet({ room: "root", role: "qa", status: "running" }),
    ).rejects.toMatchObject({ code: "forbidden" });
  });

  it("host.execute 端到端：子代理写操作 forbidden、未登记会话写操作 forbidden、子代理合法流可达", async () => {
    const { registered } = makeHost();
    await createHandlers(resolveTeamHome(SESSION_MASTER), SESSION_MASTER, rootCaller()).init({});
    // 主控建任务 + dispatch 登记 dur-q1。
    const created = (await registered.get("team_task_create")!.execute(
      { title: "t", room: "root" },
      { agent: { id: SESSION_MASTER } },
    )) as { ok: boolean; task_id: string };
    await registered.get("team_dispatch")!.execute(
      { member: MEMBER, durable_id: DUR_X, role: MEMBER, tier: 1, task_id: created.task_id },
      { agent: { id: SESSION_MASTER } },
    );
    // 子代理经 execute：spawn / taskCreate / send-from-他人 → forbidden。
    await expect(
      registered.get("team_spawn")!.execute(
        { member: "coder", durable_id: "d2", role: "coder", tier: 1 },
        { agent: { id: DUR_X } },
      ),
    ).rejects.toMatchObject({ code: "forbidden" });
    await expect(
      registered.get("team_task_create")!.execute(
        { title: "x", room: "root" },
        { agent: { id: DUR_X } },
      ),
    ).rejects.toMatchObject({ code: "forbidden" });
    await expect(
      registered.get("team_send")!.execute(
        { to: "master", from: "master", type: "info", body: { n: 1 } },
        { agent: { id: DUR_X } },
      ),
    ).rejects.toMatchObject({ code: "forbidden" });
    // 子代理经 execute 合法流：inbox 自己 + taskUpdate 自己任务可达。
    const inbox = (await registered.get("team_inbox")!.execute(
      { member: MEMBER },
      { agent: { id: DUR_X } },
    )) as { ok: boolean; unread: Array<{ id: string }> };
    expect(inbox.ok).toBe(true);
    await expect(
      registered.get("team_task_update")!.execute(
        { task_id: created.task_id, status: "running", rounds: 1 },
        { agent: { id: DUR_X } },
      ),
    ).resolves.toMatchObject({ ok: true });
    // 未登记会话经 execute：写操作 forbidden。
    await expect(
      registered.get("team_task_create")!.execute(
        { title: "x", room: "root" },
        { agent: { id: "dur-ghost" } },
      ),
    ).rejects.toMatchObject({ code: "forbidden" });
  });

  it("子代理合法流：inbox 自己 / ack 自己 / taskUpdate 自己任务 / stateSet 自己分片 / send from 自己 / handoff 自己任务", async () => {
    const { sub, taskId } = await makeTeam();
    // inbox 自己的未读信封并认领。
    const unread = (await sub.inbox({ member: MEMBER })) as {
      ok: true;
      unread: Array<{ id: string }>;
    };
    expect(unread.unread).toHaveLength(1);
    const envelopeId = unread.unread[0]!.id;
    const claimed = (await sub.inbox({ member: MEMBER, envelope_id: envelopeId })) as {
      ok: true;
      envelope: { id: string };
    };
    expect(claimed.envelope.id).toBe(envelopeId);
    // ack 自己的信封。
    await expect(
      sub.ack({ member: MEMBER, envelope_id: envelopeId }),
    ).resolves.toMatchObject({ ok: true });
    // taskUpdate 自己持有的任务（dispatch 后 assignee=qa）。
    await expect(
      sub.taskUpdate({ task_id: taskId, status: "running", rounds: 1 }),
    ).resolves.toMatchObject({ ok: true, status: "running" });
    // stateSet 自己的分片。
    await expect(
      sub.stateSet({ room: "root", role: MEMBER, status: "running" }),
    ).resolves.toMatchObject({ ok: true });
    // send from 自己。
    await expect(
      sub.send({ to: "master", from: MEMBER, type: "info", body: { n: 1 } }),
    ).resolves.toMatchObject({ ok: true });
    // handoff 自己持有的任务（qa 是 master 之外需先登记——dispatch 已登记 qa；
    // to_role 用已登记的 qa 自交回）。
    await expect(
      sub.handoff({ task_id: taskId, to_role: "qa", receipt: ["pass: done"] }),
    ).resolves.toMatchObject({ ok: true, assignee: "qa" });
  });
});

