/**
 * 宿主装配层契约：cordis apply() 注册全部 team_* 工具；execute 按
 * HANDLER_BY_TOOL 路由到 handler 并包装 {ok, ...} 输出；卸载 disposer
 * 精确注销。schema 面做结构快照断言。
 */
import { describe, expect, it, beforeEach } from "vitest";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { apply, name, inject } from "../../src/plugin/host.js";
import { schemas } from "../../src/plugin/schemas.js";
import { resolveTeamHome } from "../../src/plugin/team-home.js";
import { createHandlers, rootCaller } from "../../src/plugin/handlers.js";

interface RegisteredTool {
  name: string;
  description: string;
  parameters: unknown;
  output: { render: (args: unknown, value: unknown) => unknown };
  execute: (args: Record<string, unknown>, exec?: { agent?: { session?: { id?: string } } }) => Promise<unknown>;
}

interface RegisteredSection {
  name: string;
  order: number;
  text: string | ((context: { agent?: { id?: string } }) => string);
}

function makeHost(opts?: {
  /** #192：注入宿主 subagents 发现服务（listDescendants fake）。 */
  subagents?: {
    listDescendants: (
      rootSessionId: string,
      signal?: AbortSignal,
    ) => Promise<Array<{ kind: string; id: string; activity?: string }>>;
  };
}) {
  const registered = new Map<string, RegisteredTool>();
  const sections = new Map<string, RegisteredSection>();
  const logs: string[] = [];
  const ctx = {
    tools: {
      register: (definition: unknown) => {
        const d = definition as RegisteredTool;
        registered.set(d.name, d);
        return () => registered.delete(d.name);
      },
    },
    systemPrompt: {
      section: (definition: RegisteredSection) => {
        sections.set(definition.name, definition);
        return () => sections.delete(definition.name);
      },
      getSectionOrder: (name: string) => (name === "TEAM_POLICY" ? 600 : 100),
    },
    logger: {
      info: (msg: string) => logs.push(msg),
      warn: (msg: string) => logs.push(msg),
    },
    get(key: string) {
      if (key === "subagents" && opts?.subagents !== undefined) return opts.subagents;
      return undefined;
    },
  };
  const dispose = apply(ctx);
  return { registered, sections, logs, dispose };
}

// TEAM_HOME 指向临时目录，避免写真实 ~/.dsh
let home: string;
beforeEach(() => {
  home = mkdtempSync(join(tmpdir(), "xzg-host-"));
  process.env.DSH_HOME = join(home, "dsh-home");
});

describe("插件装配", () => {
  it("插件名与注入声明", () => {
    expect(name).toBe("xiaozhuge-team");
    expect(inject).toEqual(["tools", "webServer", "systemPrompt"]);
  });

  it("宿主 systemPrompt 在场时注册 xiaozhuge-team-orchestrator 段（ADR 0023）", async () => {
    const { sections, dispose } = makeHost();
    expect(sections.has("xiaozhuge-team-orchestrator")).toBe(true);
    const sec = sections.get("xiaozhuge-team-orchestrator")!;
    expect(sec.order).toBe(600);

    // 未初始化会话：text(context) 返回空字符串（不污染普通会话）
    const fn = sec.text as (ctx: { agent?: { id?: string } }) => string;
    expect(fn({ agent: { id: "non-team-session" } })).toBe("");
    expect(fn({})).toBe("");

    // 初始化团队会话：写入 team.yaml 后读取并返回 system_prompt
    const rootSession = "team-root-1";
    const rootHome = resolveTeamHome(rootSession);
    const handlers = createHandlers(rootHome, rootSession, rootCaller());
    await handlers.init({ scenario: "oss-maintenance" });

    const prompt = fn({ agent: { id: rootSession } });
    expect(prompt).toContain("Resource Protection Triad");
    expect(prompt).toContain("Master Scenario Orchestration (oss-maintenance)");

    // 子代理会话（无自身 team.yaml）：返回空字符串（杜绝子代理精神分裂）
    expect(fn({ agent: { id: "subagent-coder-1" } })).toBe("");

    dispose();
    expect(sections.size).toBe(0);
  });

  it("注册 12 个 team_* 工具且命名规范（team_init 已下线 #51；dispatch/reconcile 为 ADR 0015 原语）", () => {
    const { registered } = makeHost();
    const names = [...registered.keys()].sort();
    expect(names).toEqual([
      "team_ack",
      "team_dispatch",
      "team_handoff",
      "team_inbox",
      "team_reconcile",
      "team_send",
      "team_spawn",
      "team_state_get",
      "team_state_set",
      "team_task_create",
      "team_task_list",
      "team_task_update",
    ]);
  });

  it("卸载 disposer 注销全部工具", () => {
    const { registered, dispose } = makeHost();
    expect(registered.size).toBe(12);
    dispose();
    expect(registered.size).toBe(0);
  });

  it("webServer 在场时注册 Console/入口路由并订阅页面注入（#51）", () => {
    const registered = new Map<string, unknown>();
    const routes: Array<{ path: string }> = [];
    let injectCalled = false;
    const ctx = {
      tools: { register: (d: { name: string }) => {
        const disposer = () => registered.delete(d.name);
        registered.set(d.name, d);
        return disposer;
      } },
      webServer: { register: (route: { path: string }) => {
        routes.push(route);
        return () => {
          const i = routes.indexOf(route);
          if (i >= 0) routes.splice(i, 1);
        };
      } },
      logger: { info: () => {}, warn: () => {} },
      get: () => undefined,
      on: () => { injectCalled = true; },
    };
    const dispose = apply(ctx as never);
    const paths = routes.map((r) => r.path);
    expect(paths).toContain("/xiaozhuge/console");
    expect(paths).toContain("/xiaozhuge/launch");
    expect(paths).toContain("/api/xiaozhuge/team/create");
    // 页面注入已移交客户端插件（ADR 0014）：服务端不再订阅 index-inject。
    expect(injectCalled).toBe(false);
    dispose();
    expect(registered.size).toBe(0);
    expect(routes).toHaveLength(0);
  });

  it("TEAM_HOME 绑定到主会话 id（ADR 0005 宿主绑定层）", () => {
    expect(resolveTeamHome("session-abc")).toBe(
      join(process.env.DSH_HOME!, "xiaozhuge", "sessions", "session-abc"),
    );
  });
});

describe("execute 路由与输出包装", () => {
  it("team_spawn 经 execute 走到 handler 并包装 ok 输出", async () => {
    const { registered } = makeHost();
    const spawn = registered.get("team_spawn")!;
    // Wave 1b（#123）：主控身份需团队态在场（team.yaml）——先经 HTTP 面
    // init 建实例，再以主会话 execute spawn。
    await createHandlers(resolveTeamHome("session-h1"), "session-h1", rootCaller()).init({});
    const result = (await spawn.execute(
      { member: "qa", durable_id: "d-q", role: "qa", tier: 1 },
      { agent: { id: "session-h1" } },
    )) as {
      ok: boolean;
      member: string;
      durable_id: string;
    };
    expect(result.ok).toBe(true);
    expect(result.member).toBe("qa");
    // 渲染投影是 JSON 文本块
    const blocks = spawn.output.render({}, result) as Array<{ type: string; text: string }>;
    expect(blocks[0]?.type).toBe("text");
    expect(JSON.parse(blocks[0]!.text)).toMatchObject({ ok: true });
  });

  it("team_init 已下线（#51）：实例化走 HTTP 面而非 LLM 工具", () => {
    const { registered } = makeHost();
    expect(registered.get("team_init")).toBeUndefined();
  });

  it("参数缺失给 invalid-arguments（S1 结论：自行校验）", async () => {
    const { registered } = makeHost();
    await expect(
      registered.get("team_send")!.execute({ to: "x" }, { agent: { id: "s" } }),
    ).rejects.toMatchObject({ code: "invalid-arguments" });
  });

  it("spawn 后 send 可达（路由到同一实例根）", async () => {
    const { registered } = makeHost();
    const exec = { agent: { id: "session-route" } };
    // 实例化经 HTTP 面（#51）；此处直接驱动 handler 建团队态。
    await createHandlers(resolveTeamHome("session-route"), "session-route", rootCaller()).init({});
    await registered.get("team_spawn")!.execute(
      { member: "qa", durable_id: "d-q", role: "qa", tier: 1 },
      exec,
    );
    const sent = (await registered
      .get("team_send")!
      .execute({ to: "qa", from: "master", type: "info", body: { n: 1 } }, exec)) as {
      envelope_id: string;
    };
    expect(sent.envelope_id).toBeTruthy();
    const inbox = (await registered
      .get("team_inbox")!
      .execute({ member: "qa" }, exec)) as { unread: unknown[] };
    expect(inbox.unread).toHaveLength(1);
  });

  it("#192 存活探测：宿主 subagents 发现服务在场时 reconcile liveness 列为官方观测值", async () => {
    // fake listDescendants：记录树根断言 + 返回一 child 一 diagnostic。
    const probedRoots: string[] = [];
    const { registered } = makeHost({
      subagents: {
        async listDescendants(rootSessionId: string) {
          probedRoots.push(rootSessionId);
          return [
            { kind: "child", id: "dur-live", activity: "running" },
            { kind: "child", id: "dur-cold", activity: "inactive" },
            { kind: "diagnostic", id: "dur-broken", reason: "corrupt" },
          ];
        },
      },
    });
    await createHandlers(resolveTeamHome("session-live"), "session-live", rootCaller()).init({});
    await registered.get("team_spawn")!.execute(
      { member: "coder", durable_id: "dur-live", role: "coder", tier: 1 },
      { agent: { id: "session-live" } },
    );
    await registered.get("team_spawn")!.execute(
      { member: "writer", durable_id: "dur-cold", role: "writer", tier: 1 },
      { agent: { id: "session-live" } },
    );
    await registered.get("team_spawn")!.execute(
      { member: "ghost", durable_id: "dur-broken", role: "ghost", tier: 1 },
      { agent: { id: "session-live" } },
    );
    const view = (await registered.get("team_reconcile")!.execute(
      {},
      { agent: { id: "session-live" } },
    )) as {
      liveness_source: string;
      members: Array<{ member: string; liveness: string }>;
    };
    expect(view.liveness_source).toBe("subagent-discovery");
    // 探测树根 = 实例根（主会话 id），非子代理反查路径。
    expect(probedRoots).toEqual(["session-live"]);
    // kind=child → activity 直传；diagnostic → 保守缺席（missing）；
    // tier0 主控 → root-session 豁免。
    expect(view.members.find((m) => m.member === "master")?.liveness).toBe("root-session");
    expect(view.members.find((m) => m.member === "coder")?.liveness).toBe("running");
    expect(view.members.find((m) => m.member === "writer")?.liveness).toBe("inactive");
    expect(view.members.find((m) => m.member === "ghost")?.liveness).toBe("missing");
  });

  it("#192 存活探测：宿主服务未挂载 → liveness_source=unavailable（对账不阻断）", async () => {
    const { registered } = makeHost(); // 无 subagents 服务
    await createHandlers(resolveTeamHome("session-nolive"), "session-nolive", rootCaller()).init({});
    await registered.get("team_spawn")!.execute(
      { member: "qa", durable_id: "d-q2", role: "qa", tier: 1 },
      { agent: { id: "session-nolive" } },
    );
    const view = (await registered.get("team_reconcile")!.execute(
      {},
      { agent: { id: "session-nolive" } },
    )) as {
      liveness_source: string;
      members: Array<{ member: string; liveness: string }>;
    };
    expect(view.liveness_source).toBe("unavailable");
    expect(view.members.find((m) => m.member === "qa")?.liveness).toBe("framework-invisible");
  });
});

describe("schema 面", () => {
  it("每个工具 schema 有 object 参数与 required 数组", () => {
    for (const [tool, schema] of Object.entries(schemas)) {
      const params = schema.parameters as { type: string; required?: string[]; additionalProperties: boolean };
      expect(params.type, tool).toBe("object");
      expect(params.additionalProperties, tool).toBe(false);
      if (params.required !== undefined) {
        expect(Array.isArray(params.required), `${tool}.required`).toBe(true);
      }
    }
    // 关键必填项抽查
    expect((schemas.send.parameters as { required: string[] }).required).toEqual(["to", "from", "type", "body"]);
    expect((schemas.taskUpdate.parameters as { properties: { status: { enum: string[] } } }).properties.status.enum)
      .toEqual(["queued", "running", "blocked", "done", "cancelled"]);
    expect((schemas.stateSet.parameters as { properties: { status: { enum: string[] } } }).properties.status.enum)
      .toEqual(["running", "blocked", "done"]);
  });
});

