/**
 * init 预登记 tier0 主控单测（#79 L1）。
 * 覆盖：主控入册（member=tiers[0].id、durableId=宿主会话 id、status=running）、
 * 返回值 master_member、team/init 事件载荷并入（不另发 spawn 事件）、
 * 同会话重入幂等、同名异 durableId 注册被拒（member-conflict）。
 */
import { describe, expect, it, beforeEach } from "vitest";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createHandlers, rootCaller, type Handlers } from "../../src/plugin/handlers.js";
import { Registry } from "../../src/runtime/kernel/registry.js";
import { EventLog } from "../../src/runtime/kernel/event-log.js";
import { layout } from "../../src/runtime/kernel/paths.js";

let home: string;
let handlers: Handlers;
const SESSION = "session-init-master-1";

beforeEach(() => {
  home = mkdtempSync(join(tmpdir(), "xzg-init-master-"));
  handlers = createHandlers(home, SESSION, rootCaller());
});

async function readEvents(): Promise<Array<{ type: string; payload: unknown }>> {
  const log = new EventLog(join(layout(home).roomsDir, "root", "events.jsonl"));
  await log.init();
  const { events } = await log.read();
  return events.map((e) => ({ type: e.type, payload: e.payload }));
}

describe("init 预登记 tier0 主控（#79）", () => {
  it("init 即入册：member=tiers[0].id、durableId=会话 id、status=running，返回 master_member", async () => {
    const result = (await handlers.init({})) as { ok: boolean; master_member?: string };
    expect(result.ok).toBe(true);
    // builtin 默认场景 oss-maintenance 的 tiers[0].id 即 "master"。
    expect(result.master_member).toBe("master");
    const master = await new Registry(home).getMember("master");
    expect(master).toMatchObject({
      tier: 0,
      parent: null,
      durableId: SESSION,
      status: "running",
    });
    // 并入 team/init 载荷，不另发 spawn 事件（保持事件类型序列契约稳定）。
    const events = await readEvents();
    expect(events.filter((e) => e.type === "team/spawn")).toHaveLength(0);
    expect(events[0]?.type).toBe("team/init");
    expect(events[0]?.payload).toMatchObject({ master: { member: "master", outcome: "registered" } });
  });

  it("同会话重入幂等：注册表仍单条 master，事件载荷 outcome=idempotent", async () => {
    await handlers.init({});
    await handlers.init({});
    const reg = await new Registry(home).read();
    expect(Object.keys(reg.members)).toEqual(["master"]);
    const events = await readEvents();
    const payloads = events.filter((e) => e.type === "team/init").map((e) => e.payload);
    expect(payloads[1]).toMatchObject({ master: { outcome: "idempotent" } });
  });

  it("同名异 durableId 注册被拒（member-conflict）；接管路径先标 dead 后可复位", async () => {
    await handlers.init({});
    await expect(
      handlers.spawn({ member: "master", durable_id: "dur-new", role: "master", tier: 1 }),
    ).rejects.toMatchObject({ code: "member-conflict" });
    // 模拟接管核对把旧记录标 dead 后，新身份即可入册。
    const registry = new Registry(home);
    await registry.setStatus("master", "dead");
    await expect(
      handlers.spawn({ member: "master", durable_id: "dur-new", role: "master", tier: 1 }),
    ).resolves.toMatchObject({ ok: true });
  });
});

tests/plugin/member-status.test.ts.source:
/**
 * Q6（#150）成员状态机：agents.json 状态迁移由框架事件副作用驱动。
 * 覆盖：认领→running、全部完成→stopped、多任务保持 running、阻塞申报→blocked、
 * 恢复→running、同态幂等（不重复 member/status 事件）。
 */
import { describe, expect, it, beforeEach } from "vitest";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createHandlers, rootCaller, type Handlers } from "../../src/plugin/handlers.js";
import { EventLog } from "../../src/runtime/kernel/event-log.js";
import { Registry } from "../../src/runtime/kernel/registry.js";
import { layout } from "../../src/runtime/kernel/paths.js";

let home: string;
let handlers: Handlers;
const SESSION = "session-member-status";

beforeEach(() => {
  home = mkdtempSync(join(tmpdir(), "xzg-status-"));
  handlers = createHandlers(home, SESSION, rootCaller());
});

async function readEvents(): Promise<Array<{ type: string; actor: string; payload?: unknown }>> {
  const log = new EventLog(join(layout(home).roomsDir, "root", "events.jsonl"));
  await log.init();
  const { events } = await log.read();
  return events.map((e) => ({ type: e.type, actor: e.actor, payload: e.payload }));
}

async function createTask(title = "任务 X"): Promise<string> {
  const created = (await handlers.taskCreate({ title, room: "root" })) as {
    ok: true;
    task_id: string;
  };
  return created.task_id;
}

/** 以成员身份调用的 handler 实例（requireSelf/requireHolder 通过）。 */
function memberHandlers(member: string): Handlers {
  return createHandlers(home, SESSION, { kind: "member", member } as const);
}

async function seedCoder(): Promise<void> {
  await handlers.spawn({ member: "coder", durable_id: "dur-coder", role: "coder", tier: 1 });
}

describe("Q6 成员状态机（#150）", () => {
  it("认领任务（taskUpdate running）→ 成员状态 running + member/status 事件留痕", async () => {
    await handlers.init({});
    await seedCoder();
    const taskId = await createTask();
    await handlers.taskUpdate({ task_id: taskId, assignee: "coder" });
    await memberHandlers("coder").taskUpdate({ task_id: taskId, status: "running" });

    expect((await new Registry(home).getMember("coder"))?.status).toBe("running");
    const events = await readEvents();
    expect(events.find((e) => e.type === "member/status")).toMatchObject({
      actor: "system",
      payload: { member: "coder", from: "spawned", to: "running" },
    });
  });

  it("全部任务完成 → 成员状态 stopped（无其他活动任务）", async () => {
    await handlers.init({});
    await seedCoder();
    const taskId = await createTask();
    await handlers.taskUpdate({ task_id: taskId, assignee: "coder" });
    await memberHandlers("coder").taskUpdate({ task_id: taskId, status: "running" });
    await memberHandlers("coder").taskUpdate({ task_id: taskId, status: "done" });

    expect((await new Registry(home).getMember("coder"))?.status).toBe("stopped");
    const events = await readEvents();
    const toStopped = events.find(
      (e) => e.type === "member/status" && (e.payload as { to?: string })?.to === "stopped",
    );
    expect(toStopped).toBeDefined();
    expect(toStopped).toMatchObject({ payload: { from: "running", to: "stopped" } });
  });

  it("仍有其他活动任务 → 完成一个不降级 stopped（保持 running）", async () => {
    await handlers.init({});
    await seedCoder();
    const t1 = await createTask();
    const t2 = await createTask();
    await handlers.taskUpdate({ task_id: t1, assignee: "coder" });
    await handlers.taskUpdate({ task_id: t2, assignee: "coder" });
    await memberHandlers("coder").taskUpdate({ task_id: t1, status: "running" });
    await memberHandlers("coder").taskUpdate({ task_id: t2, status: "running" });
    await memberHandlers("coder").taskUpdate({ task_id: t1, status: "done" });

    expect((await new Registry(home).getMember("coder"))?.status).toBe("running");
    const events = await readEvents();
    expect(events.some((e) => (e.payload as { to?: string })?.to === "stopped")).toBe(false);
  });

  it("黑板阻塞申报 → 成员 blocked；恢复申报 → running", async () => {
    await handlers.init({});
    await seedCoder();
    await memberHandlers("coder").stateSet({ room: "root", role: "coder", status: "blocked" });
    expect((await new Registry(home).getMember("coder"))?.status).toBe("blocked");
    expect((await readEvents()).find((e) => e.type === "member/status")).toMatchObject({
      payload: { from: "spawned", to: "blocked" },
    });

    await memberHandlers("coder").stateSet({ room: "root", role: "coder", status: "running" });
    expect((await new Registry(home).getMember("coder"))?.status).toBe("running");
  });

  it("同态幂等：重复阻塞申报不重复 member/status 事件", async () => {
    await handlers.init({});
    await seedCoder();
    await memberHandlers("coder").stateSet({ room: "root", role: "coder", status: "blocked" });
    // 第二次同态申报：transitMemberStatus 幂等跳过，不重复留痕
    // （任务状态机本身禁止 running→running，故幂等路径走黑板申报验证）。
    await memberHandlers("coder").stateSet({ room: "root", role: "coder", status: "blocked" });

    const events = await readEvents();
    expect(events.filter((e) => e.type === "member/status")).toHaveLength(1);
  });

  it("存量兼容：spawned 且任务全部 done → reconcile 展示 stopped（读路径，不写盘）", async () => {
    await handlers.init({});
    await seedCoder();
    const taskId = await createTask();
    await handlers.taskUpdate({ task_id: taskId, assignee: "coder" });
    await memberHandlers("coder").taskUpdate({ task_id: taskId, status: "running" });
    await memberHandlers("coder").taskUpdate({ task_id: taskId, status: "done" });
    // 模拟 PR-1 前存量：状态机从不迁移，成员仍停在 spawned。
    await new Registry(home).setStatus("coder", "spawned");

    const view = (await handlers.reconcile({})) as {
      members: Array<{ member: string; status: string }>;
    };
    expect(view.members.find((m) => m.member === "coder")?.status).toBe("stopped");
    // 读路径语义适配：不写盘，agents.json 仍为 spawned。
    expect((await new Registry(home).getMember("coder"))?.status).toBe("spawned");
  });

  it("存量兼容：spawned 且无任务记录 → 保持 spawned（从未派活）", async () => {
    await handlers.init({});
    await seedCoder();
    const view = (await handlers.reconcile({})) as {
      members: Array<{ member: string; status: string }>;
    };
    expect(view.members.find((m) => m.member === "coder")?.status).toBe("spawned");
  });
});

tests/plugin/playbook-guard.test.ts.source:
/**
 * Tier-0 规程分层与组装守门（issue #42，增量 ADR 0009）。
 *
 * 三道闸：
 * 1. 分隔符格式锁定——分隔符是显式协议常量，改动即协议变更；
 * 2. 正向组装——init 返回值（HTTP 面经 /api/xiaozhuge/team/create，工具面已下线）
 *    = 规程全文 + 分隔符 + 场景 tiers[0].prompt，
 *   对任意场景成立（含单层 research-report，#39 依赖方）；
 * 3. 反向守门——内置模板场景 prompt 不得复制规程特征句，防双副本漂移复发。
 */
import { describe, expect, it, beforeEach } from "vitest";
import { existsSync, mkdtempSync, readFileSync, readdirSync } from "node:fs";
import { readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { createHash } from "node:crypto";
import {
  assembleTier0Prompt,
  instantiateSnapshot,
  loadTemplate,
  loadTier0Playbook,
  PLAYBOOKS_DIR,
  TIER0_PLAYBOOK_FILE,
  TIER0_PLAYBOOK_SEPARATOR,
} from "../../src/index.js";
import { createHandlers, rootCaller, type Handlers } from "../../src/plugin/handlers.js";
import { appendToolManifest, TOOL_MANIFEST_SEPARATOR } from "../../src/plugin/tool-manifest.js";

const REPO_ROOT = join(fileURLToPath(new URL(".", import.meta.url)), "..", "..");
const OSS_DIR = join(REPO_ROOT, "templates", "oss-maintenance");
const RR_DIR = join(REPO_ROOT, "templates", "research-report");
const PLAYBOOK_PATH = join(REPO_ROOT, PLAYBOOKS_DIR, TIER0_PLAYBOOK_FILE);

/** 规程正文独有的特征句（框架协议知识，场景层不得复制，ADR 0023 英文重构）。 */
const PLAYBOOK_SIGNATURES = [
  "Resource Protection Triad",
  "Startup Reconciliation",
  "State-Level Recovery",
  "blocked_streak",
  "Operational Invariants",
  "Objective Anchoring",
  "Low-Cost Inspection Turn",
  "Max-Tokens Disarm Protection",
];

describe("分隔符协议常量", () => {
  // 格式锁定：本断言变化 = 协议变更，须走增量 ADR。
  it("分隔符确切格式被锁定", () => {
    expect(TIER0_PLAYBOOK_SEPARATOR).toBe(
      "\n\n===== tier0 playbook / scenario prompt boundary =====\n\n",
    );
  });
});

describe("规程加载（playbooks/ 唯一事实源）", () => {
  it("全文读入且 digest 为源文件 sha256 前 16 位", () => {
    const playbook = loadTier0Playbook(REPO_ROOT);
    const raw = readFileSync(PLAYBOOK_PATH, "utf8");
    expect(playbook.text).toBe(raw);
    expect(playbook.digest).toBe(createHash("sha256").update(raw).digest("hex").slice(0, 16));
    expect(playbook.digest).toMatch(/^[0-9a-f]{16}$/);
  });

  it("规程文件随包存在于 playbooks/ 落点", () => {
    expect(existsSync(PLAYBOOK_PATH)).toBe(true);
    expect(existsSync(join(REPO_ROOT, "docs", "patrol", "tier0-playbook.md"))).toBe(false);
  });
});

describe("正向组装：tier0_prompt = 规程全文 + 分隔符 + 场景段", () => {
  let home: string;
  let handlers: Handlers;
  beforeEach(() => {
    home = mkdtempSync(join(tmpdir(), "xzg-pb-"));
    handlers = createHandlers(home, "session-playbook-1", rootCaller());
  });

  it("init 组装结果逐字节等于公式（ADR 0015：尾部追加工具面自述保留段），快照记录 playbook_digest", async () => {
    const result = (await handlers.init({})) as {
      tier0_prompt: string;
      playbook_digest: string;
    };
    const playbook = loadTier0Playbook(REPO_ROOT);
    const scenarioPrompt = readFileSync(join(OSS_DIR, "prompts", "master.md"), "utf8");
    expect(result.tier0_prompt).toBe(
      appendToolManifest(assembleTier0Prompt(playbook, scenarioPrompt)),
    );
    // 规程全文完整在场（#11 缺口不回潮）；保留段在规程与场景段之后
    expect(result.tier0_prompt).toContain(playbook.text);
    expect(result.tier0_prompt.indexOf(TOOL_MANIFEST_SEPARATOR)).toBeGreaterThan(
      result.tier0_prompt.indexOf(TIER0_PLAYBOOK_SEPARATOR),
    );
    expect(result.playbook_digest).toBe(playbook.digest);
    // 快照审计字段
    const snapshot = JSON.parse(await readFile(join(home, "team.yaml"), "utf8")) as {
      playbook_digest?: string;
    };
    expect(snapshot.playbook_digest).toBe(playbook.digest);
  });

  it("research-report（单层场景）经同一组装公式同样获得规程全文（#39 依赖）", async () => {
    const loaded = await loadTemplate(RR_DIR, "builtin");
    const playbook = loadTier0Playbook(REPO_ROOT);
    const scenarioPrompt = loaded.prompts["./prompts/master.md"] ?? "";
    const assembled = assembleTier0Prompt(playbook, scenarioPrompt);
    expect(scenarioPrompt.length).toBeGreaterThan(0);
    expect(assembled).toContain(playbook.text);
    expect(assembled.indexOf(playbook.text)).toBeLessThan(assembled.indexOf(TIER0_PLAYBOOK_SEPARATOR));
  });

  it("旧口径兼容：instantiateSnapshot 不传 digest 时快照字段为 null", async () => {
    const loaded = await loadTemplate(OSS_DIR, "builtin");
    const snapshot = instantiateSnapshot(loaded) as { playbook_digest: unknown };
    expect(snapshot.playbook_digest).toBeNull();
  });
});

describe("反向守门：内置模板场景 prompt 不得复制规程特征句", () => {
  it("templates/*/prompts/*.md 全量扫描零命中", () => {
    const templatesDir = join(REPO_ROOT, "templates");
    for (const scenario of readdirSync(templatesDir)) {
      const promptsDir = join(templatesDir, scenario, "prompts");
      if (!existsSync(promptsDir)) continue;
      for (const file of readdirSync(promptsDir)) {
        const content = readFileSync(join(promptsDir, file), "utf8");
        for (const sig of PLAYBOOK_SIGNATURES) {
          expect(content.includes(sig), `${scenario}/prompts/${file} 含规程特征句「${sig}」`).toBe(false);
        }
      }
    }
  });

  it("特征句清单本身仍全部命中现行规程（防守门空转）", () => {
    const playbookText = readFileSync(PLAYBOOK_PATH, "utf8");
    for (const sig of PLAYBOOK_SIGNATURES) {
      expect(playbookText.includes(sig), `特征句「${sig}」已不在规程中，须更新清单`).toBe(true);
    }
  });
});

tests/plugin/reconcile.test.ts.source:
/**
 * team_reconcile 对账原语单测（ADR 0015 决策 1，#66）。
 * 覆盖：overview 全量视图（成员对照 / 悬空指派 / 状态分布 / 事件游标 /
 * goal 占位）、stale 心跳标注矩阵（master_idle / stale_members /
 * awaiting_input，#97 ADR 0016）、scope=audit 旁路 report-only（未登记
 * 文件 / 过期登记 / 敏感名掩码 / 无工作区不可用）、参数校验。
 */
import { describe, expect, it, beforeEach, afterEach, vi } from "vitest";
import { mkdirSync, mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createHandlers, rootCaller, type Handlers } from "../../src/plugin/handlers.js";
import { Registry, STALE_THRESHOLD_MS } from "../../src/index.js";
import { DEFAULT_DELIVERING_TTL_MS } from "../../src/runtime/kernel/recovery.js";
import type { MemberRecord } from "../../src/runtime/kernel/types.js";

let home: string;
let handlers: Handlers;
let workspace: string;
const SESSION = "session-reconcile-1";

beforeEach(() => {
  home = mkdtempSync(join(tmpdir(), "xzg-rec-home-"));
  workspace = mkdtempSync(join(tmpdir(), "xzg-rec-ws-"));
  handlers = createHandlers(home, SESSION, rootCaller());
});

describe("team_reconcile overview", () => {
  it("一次调用返回快照摘要、成员对照、状态分布、事件游标与 goal 占位", async () => {
    await handlers.init({ project_root: workspace });
    await handlers.spawn({ member: "coder", durable_id: "dur-coder", role: "coder", tier: 1 });
    const t = (await handlers.taskCreate({
      title: "实现 X",
      room: "root",
      assignee: "coder",
      touched_paths: ["src/a.ts"],
    })) as { task_id: string };
    // 悬空指派：账本有 assignee、注册表无此成员。
    await handlers.taskUpdate({ task_id: t.task_id, assignee: "ghost" });

    const view = (await handlers.reconcile({})) as {
      ok: boolean;
      scope: string;
      initialized: boolean;
      snapshot: { source: string | null; workspace_seen?: unknown };
      members: Array<{ member: string; liveness: string; assigned_task_ids: string[] }>;
      dangling_assignees: string[];
      orphan_members: Array<{ member: string; tier: number; parent: string | null; reason: string }>;
      master_idle: boolean;
      stale_members: Array<{ member: string; last_seen_age_ms: number }>;
      awaiting_input: Array<{ member: string; last_seen_age_ms: number }>;
      task_status_counts: Record<string, number>;
      event_cursors: Array<{ room: string; seq: number }>;
      goal_binding: string;
      tool_manifest_pointer: string;
    };

    expect(view.ok).toBe(true);
    expect(view.scope).toBe("overview");
    expect(view.initialized).toBe(true);
    expect(view.snapshot?.source).toBe("builtin");
    expect(view.members).toHaveLength(2);
    // init 预登记的 tier0 主控（#79）：durableId = 宿主会话 id，对账可见。
    expect(view.members.find((m) => m.member === "master")).toMatchObject({
      durable_id: SESSION,
      liveness: "framework-invisible",
    });
    expect(view.members.find((m) => m.member === "coder")).toMatchObject({
      member: "coder",
      durable_id: "dur-coder",
      liveness: "framework-invisible",
    });
    expect(view.dangling_assignees).toEqual(["ghost"]);
    // 孤儿标红（report-only）：spawn 未传 parent → coder 标 parent-missing；
    // tier0 主控豁免（单入口原则）。
    expect(view.orphan_members).toEqual([
      { member: "coder", tier: 1, parent: null, reason: "parent-missing" },
    ]);
    // stale 心跳标注默认态（#97）：全员新鲜时零标注（golden 契约同步锚点）。
    expect(view.master_idle).toBe(false);
    expect(view.stale_members).toEqual([]);
    expect(view.awaiting_input).toEqual([]);
    expect(view.task_status_counts).toEqual({ queued: 1 });
    expect(view.event_cursors[0]?.room).toBe("root");
    expect(view.event_cursors[0]!.seq).toBeGreaterThan(0);
    expect(view.goal_binding).toContain("framework-invisible");
    expect(view.goal_binding).toContain("get_goal");
    expect(view.tool_manifest_pointer).toContain("tool manifest");
  });

  it("未初始化实例返回 initialized=false 且不抛错", async () => {
    const view = (await handlers.reconcile({})) as { initialized: boolean; snapshot: unknown };
    expect(view.initialized).toBe(false);
    expect(view.snapshot).toBeNull();
  });

  it("孤儿标红：有 parent 且在册不标；悬空 parent 标 parent-dangling", async () => {
    await handlers.init({ project_root: workspace });
    // coder 带合法 parent（master 由 init 预登记）→ 不标。
    await handlers.spawn({
      member: "coder",
      durable_id: "dur-coder",
      role: "coder",
      tier: 1,
      parent: "master",
    });
    // painter 的 parent 未注册 → 标 parent-dangling。
    await handlers.spawn({
      member: "painter",
      durable_id: "dur-painter",
      role: "painter",
      tier: 1,
      parent: "ghost-parent",
    });

    const view = (await handlers.reconcile({})) as {
      orphan_members: Array<{ member: string; tier: number; parent: string | null; reason: string }>;
    };
    expect(view.orphan_members).toEqual([
      { member: "painter", tier: 1, parent: "ghost-parent", reason: "parent-dangling" },
    ]);
  });

  it("互斥冲突标注恒在场（空数组形态）——T10 契约断言（#137）", async () => {
    await handlers.init({ project_root: workspace });
    const view = (await handlers.reconcile({})) as {
      active_mutex_conflicts: Array<{ a: string; b: string; reason: string }>;
    };
    expect(view.active_mutex_conflicts).toEqual([]);
  });

  it("T1 单任务 queued→running 无邻居 → 不标冲突", async () => {
    await handlers.init({ project_root: workspace });
    const t = (await handlers.taskCreate({
      title: "T1",
      room: "root",
      touched_paths: ["src/a.ts"],
      mutex_groups: ["g1"],
    })) as { task_id: string };
    await handlers.taskUpdate({ task_id: t.task_id, status: "running" });
    const view = (await handlers.reconcile({})) as {
      active_mutex_conflicts: Array<{ a: string; b: string; reason: string }>;
    };
    expect(view.active_mutex_conflicts).toEqual([]);
  });

  it("T3 同组先后 create 均 queued 共存 → 不标（尚非 running）", async () => {
    await handlers.init({ project_root: workspace });
    const t1 = (await handlers.taskCreate({
      title: "T3a", room: "root", mutex_groups: ["g1"],
    })) as { task_id: string };
    const t2 = (await handlers.taskCreate({
      title: "T3b", room: "root", mutex_groups: ["g1"],
    })) as { task_id: string };
    void t1;
    void t2;
    const view = (await handlers.reconcile({})) as {
      active_mutex_conflicts: Array<{ a: string; b: string; reason: string }>;
    };
    expect(view.active_mutex_conflicts).toEqual([]);
  });

  it("T4-RO B 转 running 撞 running 的 A（同组）→ 冲突对入标注", async () => {
    await handlers.init({ project_root: workspace });
    const a = (await handlers.taskCreate({
      title: "A", room: "root", mutex_groups: ["g1"],
    })) as { task_id: string };
    const b = (await handlers.taskCreate({
      title: "B", room: "root", mutex_groups: ["g1"],
    })) as { task_id: string };
    await handlers.taskUpdate({ task_id: a.task_id, status: "running" });
    await handlers.taskUpdate({ task_id: b.task_id, status: "running" });
    const view = (await handlers.reconcile({})) as {
      active_mutex_conflicts: Array<{ a: string; b: string; reason: string }>;
    };
    expect(view.active_mutex_conflicts).toHaveLength(1);
    expect(view.active_mutex_conflicts[0]!.reason).toContain("shared mutex group: g1");
    // 冲突对双方为 A/B（次序无关）。
    const pair = [view.active_mutex_conflicts[0]!.a, view.active_mutex_conflicts[0]!.b].sort();
    expect(pair).toEqual([a.task_id, b.task_id].sort());
  });

  it("T5-RO touched 字面交集撞车 → 冲突对入标注", async () => {
    await handlers.init({ project_root: workspace });
    const a = (await handlers.taskCreate({
      title: "A", room: "root", touched_paths: ["src/x.ts"],
    })) as { task_id: string };
    const b = (await handlers.taskCreate({
      title: "B", room: "root", touched_paths: ["src/x.ts"],
    })) as { task_id: string };
    await handlers.taskUpdate({ task_id: a.task_id, status: "running" });
    await handlers.taskUpdate({ task_id: b.task_id, status: "running" });
    const view = (await handlers.reconcile({})) as {
      active_mutex_conflicts: Array<{ a: string; b: string; reason: string }>;
    };
    expect(view.active_mutex_conflicts).toHaveLength(1);
    expect(view.active_mutex_conflicts[0]!.reason).toContain("touched path overlap: src/x.ts");
  });

  it("T5-盲 A 双字段并存：判定次序先 mutexGroups 后 touched，reason 固定为 mutex（#137）", async () => {
    await handlers.init({ project_root: workspace });
    const a = (await handlers.taskCreate({
      title: "A", room: "root",
      touched_paths: ["src/x.ts"], mutex_groups: ["g1"],
    })) as { task_id: string };
    const b = (await handlers.taskCreate({
      title: "B", room: "root",
      touched_paths: ["src/x.ts"], mutex_groups: ["g1"],
    })) as { task_id: string };
    await handlers.taskUpdate({ task_id: a.task_id, status: "running" });
    await handlers.taskUpdate({ task_id: b.task_id, status: "running" });
    const view = (await handlers.reconcile({})) as {
      active_mutex_conflicts: Array<{ a: string; b: string; reason: string }>;
    };
    expect(view.active_mutex_conflicts).toHaveLength(1);
    expect(view.active_mutex_conflicts[0]!.reason).toContain("shared mutex group: g1");
  });

  it("T7 异 room 共享组 → 不冲突（room 隔离）", async () => {
    await handlers.init({ project_root: workspace });
    const a = (await handlers.taskCreate({
      title: "A", room: "root", mutex_groups: ["g1"],
    })) as { task_id: string };
    const b = (await handlers.taskCreate({
      title: "B", room: "work", mutex_groups: ["g1"],
    })) as { task_id: string };
    await handlers.taskUpdate({ task_id: a.task_id, status: "running" });
    await handlers.taskUpdate({ task_id: b.task_id, status: "running" });
    const view = (await handlers.reconcile({})) as {
      active_mutex_conflicts: Array<{ a: string; b: string; reason: string }>;
    };
    expect(view.active_mutex_conflicts).toEqual([]);
  });

  it("T8 done/cancelled/blocked 作参照方 → 不入比较集", async () => {
    await handlers.init({ project_root: workspace });
    const running = (await handlers.taskCreate({
      title: "running", room: "root", mutex_groups: ["g1"],
    })) as { task_id: string };
    const done = (await handlers.taskCreate({
      title: "done", room: "root", mutex_groups: ["g1"],
    })) as { task_id: string };
    const blocked = (await handlers.taskCreate({
      title: "blocked", room: "root", mutex_groups: ["g1"],
    })) as { task_id: string };
    await handlers.taskUpdate({ task_id: running.task_id, status: "running" });
    // done 也只能由 running 迁入（queued→done 非法，types.ts:40-46）。
    await handlers.taskUpdate({ task_id: done.task_id, status: "running" });
    await handlers.taskUpdate({ task_id: done.task_id, status: "done" });
    // blocked 同理。
    await handlers.taskUpdate({ task_id: blocked.task_id, status: "running" });
    await handlers.taskUpdate({ task_id: blocked.task_id, status: "blocked" });
    const view = (await handlers.reconcile({})) as {
      active_mutex_conflicts: Array<{ a: string; b: string; reason: string }>;
    };
    expect(view.active_mutex_conflicts).toEqual([]);
  });
});

describe("team_reconcile stale 心跳标注（#97 ADR 0016）", () => {
  const NOW = 1_700_000_000_000;
  const STALE_TS = NOW - STALE_THRESHOLD_MS - 60_000; // 超阈一分钟

  beforeEach(() => {
    vi.useFakeTimers();
    vi.setSystemTime(NOW);
  });
  afterEach(() => {
    vi.useRealTimers();
  });

  /** 直接改写 agents.json 中某成员记录（绕过工具面构造任意 lastSeen/status）。 */
  async function seedMember(name: string, patch: Partial<MemberRecord>): Promise<void> {
    const reg = new Registry(home);
    const data = await reg.read();
    if (data.members[name] === undefined) throw new Error(`member ${name} not seeded`);
    Object.assign(data.members[name]!, patch);
    await reg.write(data);
  }

  async function reconcile(): Promise<{
    master_idle: boolean;
    stale_members: Array<{ member: string; last_seen_age_ms: number }>;
    awaiting_input: Array<{ member: string; last_seen_age_ms: number }>;
  }> {
    return (await handlers.reconcile({})) as never;
  }

  it("全员新鲜 → master_idle=false 且两档名册皆空", async () => {
    await handlers.init({});
    await handlers.spawn({ member: "coder", durable_id: "dur-coder", role: "coder", tier: 1 });
    await seedMember("coder", { status: "running" });
    const view = await reconcile();
    expect(view.master_idle).toBe(false);
    expect(view.stale_members).toEqual([]);
    expect(view.awaiting_input).toEqual([]);
  });

  it("running 成员超阈入 stale_members 并携带静默时长；主控不入名册", async () => {
    await handlers.init({});
    await handlers.spawn({ member: "coder", durable_id: "dur-coder", role: "coder", tier: 1 });
    await seedMember("coder", { status: "running", lastSeen: STALE_TS });
    const view = await reconcile();
    expect(view.stale_members).toEqual([{ member: "coder", last_seen_age_ms: NOW - STALE_TS }]);
    expect(view.stale_members.map((m) => m.member)).not.toContain("master");
    expect(view.master_idle).toBe(false);
  });

  it("tier0 主控超阈仅亮 master_idle（消除自刷矛盾与续命放大通道）", async () => {
    await handlers.init({});
    await handlers.spawn({ member: "coder", durable_id: "dur-coder", role: "coder", tier: 1 });
    await seedMember("master", { lastSeen: STALE_TS });
    const view = await reconcile();
    expect(view.master_idle).toBe(true);
    expect(view.stale_members).toEqual([]);
  });

  it("dead / spawned / stopped 一律不收录（lost 与非干活中豁免）", async () => {
    await handlers.init({});
    for (const m of ["dead-one", "spawned-one", "stopped-one"]) {
      await handlers.spawn({ member: m, durable_id: `dur-${m}`, role: m, tier: 1 });
    }
    await seedMember("dead-one", { status: "dead", lastSeen: STALE_TS });
    await seedMember("spawned-one", { status: "spawned", lastSeen: STALE_TS });
    await seedMember("stopped-one", { status: "stopped", lastSeen: STALE_TS });
    const view = await reconcile();
    expect(view.stale_members).toEqual([]);
    expect(view.awaiting_input).toEqual([]);
  });

  it("超阈且黑板任一分片 blocked 归 awaiting_input 免责档，不再双列", async () => {
    await handlers.init({});
    await handlers.spawn({ member: "waiter", durable_id: "dur-waiter", role: "waiter", tier: 1 });
    // 先置 blocked 分片再回拨时钟：state_set 会刷 waiter lastSeen 到当前。
    await handlers.stateSet({ room: "root", role: "waiter", status: "blocked" });
    await seedMember("waiter", { status: "running", lastSeen: STALE_TS });
    const view = await reconcile();
    expect(view.awaiting_input).toEqual([{ member: "waiter", last_seen_age_ms: NOW - STALE_TS }]);
    expect(view.stale_members).toEqual([]);
  });

  it("自属分片跨房间聚合：第二房间 blocked 同样免责；无分片对照者照常入 stale_members", async () => {
    await handlers.init({});
    await handlers.spawn({ member: "w1", durable_id: "dur-w1", role: "w1", tier: 1 });
    await handlers.spawn({
      member: "bystander", durable_id: "dur-bystander", role: "bystander", tier: 1,
    });
    // w1 的自属 blocked 分片写入第二房间（非 root）：豁免语义＝其分片在
    // 任一房间 blocked 即免责（blockedIndex 按角色跨房间聚合）；room 仅
    // 命名空间非权限边界（#123 口径），stateSet 可直接构造新房间。
    // state_set 会刷 lastSeen 到当前，先写分片再回拨时钟。
    await handlers.stateSet({ room: "work", role: "w1", status: "blocked" });
    await seedMember("w1", { status: "running", lastSeen: STALE_TS });
    await seedMember("bystander", { status: "running", lastSeen: STALE_TS });
    const view = await reconcile();
    expect(view.awaiting_input).toEqual([{ member: "w1", last_seen_age_ms: NOW - STALE_TS }]);
    expect(view.stale_members).toEqual([
      { member: "bystander", last_seen_age_ms: NOW - STALE_TS },
    ]);
  });

  it("恰达阈值不标（严格大于，宁少标勿错标）；未来时间戳（挂钟回拨）同样不标", async () => {
    await handlers.init({});
    await handlers.spawn({ member: "edge", durable_id: "dur-edge", role: "edge", tier: 1 });
    await handlers.spawn({ member: "future", durable_id: "dur-future", role: "future", tier: 1 });
    await seedMember("edge", { status: "running", lastSeen: NOW - STALE_THRESHOLD_MS }); // age 恰等于阈值
    await seedMember("future", { status: "running", lastSeen: NOW + 600_000 });
    const view = await reconcile();
    expect(view.stale_members).toEqual([]);
  });

  it("STALE_THRESHOLD_MS 锚点恒等：3× delivering TTL（协议常量区与 recovery 层不漂移脱钩）", () => {
    // types.ts 受 kernel 零反向依赖约束不能 import recovery.ts，
    // 锚点关系只能在测试层锁定（审核建议 1）。
    expect(STALE_THRESHOLD_MS).toBe(3 * DEFAULT_DELIVERING_TTL_MS);
  });

  it("多名册按 member 字典序稳定输出（不随注册顺序漂移）", async () => {
    await handlers.init({});
    // 故意以逆字典序登记。
    for (const m of ["zeta", "mid", "alpha"]) {
      await handlers.spawn({ member: m, durable_id: `dur-${m}`, role: m, tier: 1 });
      await seedMember(m, { status: "running", lastSeen: STALE_TS });
    }
    const view = await reconcile();
    expect(view.stale_members.map((m) => m.member)).toEqual(["alpha", "mid", "zeta"]);
    // age 一致（同 lastSeen），形态完整。
    expect(view.stale_members.every((m) => m.last_seen_age_ms === NOW - STALE_TS)).toBe(true);
  });
});

describe("#192 存活核对官方化（subagent 发现 API 注入）", () => {
  /** 构造带 livenessProbe 的 handlers：probe 返回固定 durableId → activity 映射。 */
  function withProbe(
    map: Map<string, "running" | "inactive">,
  ): Handlers {
    return createHandlers(home, SESSION, rootCaller(), async () => map);
  }

  it("探测命中：liveness 列升级为官方观测值，liveness_source=subagent-discovery", async () => {
    await handlers.init({ project_root: workspace });
    await handlers.spawn({ member: "coder", durable_id: "dur-c1", role: "coder", tier: 1 });
    await handlers.spawn({ member: "writer", durable_id: "dur-w1", role: "writer", tier: 1 });
    const probed = withProbe(
      new Map([
        ["dur-c1", "running"],
        ["dur-w1", "inactive"],
      ]),
    );
    const view = (await probed.reconcile({})) as {
      liveness_source: string;
      members: Array<{ member: string; tier: number; liveness: string }>;
    };
    expect(view.liveness_source).toBe("subagent-discovery");
    // tier0 主控 = 宿主主会话，不经 subagent 面 → root-session。
    expect(view.members.find((m) => m.member === "master")?.liveness).toBe("root-session");
    expect(view.members.find((m) => m.member === "coder")?.liveness).toBe("running");
    expect(view.members.find((m) => m.member === "writer")?.liveness).toBe("inactive");
  });

  it("发现面枚举不到的成员 → missing（保守缺席，供主控对账判 dead）", async () => {
    await handlers.init({ project_root: workspace });
    await handlers.spawn({ member: "coder", durable_id: "dur-c2", role: "coder", tier: 1 });
    const probed = withProbe(new Map()); // 空枚举 = 全员缺席
    const view = (await probed.reconcile({})) as {
      members: Array<{ member: string; liveness: string }>;
    };
    expect(view.members.find((m) => m.member === "coder")?.liveness).toBe("missing");
  });

  it("探测抛错 → 退化为 framework-invisible 旧口径（liveness_source=unavailable），不阻断对账", async () => {
    await handlers.init({ project_root: workspace });
    await handlers.spawn({ member: "coder", durable_id: "dur-c3", role: "coder", tier: 1 });
    const failing = createHandlers(home, SESSION, rootCaller(), async () => {
      throw new Error("discovery unavailable");
    });
    const view = (await failing.reconcile({})) as {
      liveness_source: string;
      members: Array<{ member: string; liveness: string }>;
      initialized: boolean;
      task_status_counts: Record<string, number>;
    };
    expect(view.liveness_source).toBe("unavailable");
    expect(view.members.find((m) => m.member === "coder")?.liveness).toBe("framework-invisible");
    // 对账主体不受探测失败影响。
    expect(view.initialized).toBe(true);
    expect(view.task_status_counts).toEqual({});
  });

  it("未注入探测回调（既有路径）→ 全员 framework-invisible（行为不变）", async () => {
    await handlers.init({ project_root: workspace });
    await handlers.spawn({ member: "coder", durable_id: "dur-c4", role: "coder", tier: 1 });
    const view = (await handlers.reconcile({})) as {
      liveness_source: string;
      members: Array<{ member: string; liveness: string }>;
    };
    expect(view.liveness_source).toBe("unavailable");
    expect(view.members.every((m) => m.liveness === "framework-invisible")).toBe(true);
  });
});

describe("team_reconcile scope=audit", () => {
  it("双向 diff：未登记文件命中、登记在案不误报、过期登记入 stale", async () => {
    // 工作树：src/a.ts（将登记）+ build.log（不登记）。
    mkdirSync(join(workspace, "src"), { recursive: true });
    writeFileSync(join(workspace, "src", "a.ts"), "export {};\n");
    writeFileSync(join(workspace, "build.log"), "noise\n");

    await handlers.init({ project_root: workspace });
    await handlers.taskCreate({
      title: "T",
      room: "root",
      touched_paths: ["src/a.ts", "gone/missing.ts"],
    });

    const view = (await handlers.reconcile({ scope: "audit" })) as {
      audit: {
        available: boolean;
        scanned_root: string;
        unregistered_files: Array<{ path: string; size: number; sensitive_masked: boolean }>;
        stale_registered_paths: string[];
        truncated: boolean;
      };
    };

    expect(view.audit.available).toBe(true);
    expect(view.audit.scanned_root).toBe(workspace);
    const paths = view.audit.unregistered_files.map((f) => f.path);
    expect(paths).toContain("build.log");
    expect(paths).not.toContain(join("src", "a.ts"));
    expect(view.audit.stale_registered_paths).toEqual(["gone/missing.ts"]);
    expect(view.audit.truncated).toBe(false);
    // 元数据形态：size/mtime 为数值，绝无内容字段。
    const f = view.audit.unregistered_files.find((x) => x.path === "build.log")!;
    expect(typeof f.size).toBe("number");
    expect(f.sensitive_masked).toBe(false);
    expect(Object.keys(f)).not.toContain("content");
  });

  it("敏感文件名打掩码，完整名不外泄", async () => {
    writeFileSync(join(workspace, ".env.local"), "SECRET=1\n");
    await handlers.init({ project_root: workspace });
    const view = (await handlers.reconcile({ scope: "audit" })) as {
      audit: { unregistered_files: Array<{ path: string; sensitive_masked: boolean }> };
    };
    const masked = view.audit.unregistered_files.find((f) => f.sensitive_masked);
    expect(masked).toBeDefined();
    expect(masked!.path).not.toContain(".env.local");
    expect(masked!.path.endsWith("<masked:sensitive-name>")).toBe(true);
  });

  it("旧快照无 workspace 字段 → 审计诚实标注不可用", async () => {
    await handlers.init({});
    const view = (await handlers.reconcile({ scope: "audit" })) as {
      audit: { available: boolean; reason: string };
    };
    expect(view.audit.available).toBe(false);
    expect(view.audit.reason).toContain("audit unavailable");
  });
});

